  function prettifyCharacterSheetLabel(pathValue) {
    const baseName = String(pathValue || "")
      .split("/")
      .pop()
      .replace(/\.[^.]+$/, "")
      .replace(/[_-]+/g, " ")
      .trim();
    return baseName
      .split(/\s+/)
      .filter(Boolean)
      .map(function (part) {
        return part.charAt(0).toUpperCase() + part.slice(1);
      })
      .join(" ");
  }

